    22	    const [searchValue, setSearchValue] = useState('');
    23	    const {translate} = useLocalize();
    24	    const getUnselectedOptions = useCallback((options: CurrencyListItem[]) => options.filter((option) => !option.isSelected), []);
    25	    const {sections, headerMessage} = useMemo(() => {
    26	        const currencyOptions: CurrencyListItem[] = Object.entries(currencyList ?? {}).reduce((acc, [currencyCode, currencyInfo]) => {
    27	            const isSelectedCurrency = currencyCode === initiallySelectedCurrencyCode || selectedCurrencies.includes(currencyCode);
    28	            if (isSelectedCurrency || !currencyInfo?.retired) {
    29	                acc.push({
    30	                    currencyName: currencyInfo?.name ?? '',
    31	                    text: `${currencyCode} - ${CurrencyUtils.getCurrencySymbol(currencyCode)}`,
    32	                    currencyCode,
    33	                    keyForList: currencyCode,
    34	                    isSelected: isSelectedCurrency,
    35	                });
    36	            }
    37	            return acc;
    38	        }, [] as CurrencyListItem[]);
    39	
    40	        const recentlyUsedCurrencyOptions: CurrencyListItem[] = Array.isArray(recentlyUsedCurrencies)
    41	            ? recentlyUsedCurrencies?.map((currencyCode) => {
    42	                  const currencyInfo = currencyList?.[currencyCode];
    43	                  const isSelectedCurrency = currencyCode === initiallySelectedCurrencyCode;
    44	                  return {
    45	                      currencyName: currencyInfo?.name ?? '',
    46	                      text: `${currencyCode} - ${CurrencyUtils.getCurrencySymbol(currencyCode)}`,
    47	                      currencyCode,
    48	                      keyForList: currencyCode,
    49	                      isSelected: isSelectedCurrency,
    50	                  };
    51	              })
    52	            : [];
    53	
    54	        const searchRegex = new RegExp(Str.escapeForRegExp(searchValue.trim()), 'i');
    55	        const filteredCurrencies = currencyOptions.filter((currencyOption) => searchRegex.test(currencyOption.text ?? '') || searchRegex.test(currencyOption.currencyName));
    56	        const isEmpty = searchValue.trim() && !filteredCurrencies.length;
    57	        const shouldDisplayRecentlyOptions = !isEmptyObject(recentlyUsedCurrencyOptions) && !searchValue;
    58	        const selectedOptions = filteredCurrencies.filter((option) => option.isSelected);
    59	        const shouldDisplaySelectedOptionOnTop = selectedOptions.length > 0;
    60	        const unselectedOptions = getUnselectedOptions(filteredCurrencies);
    61	        const result = [];
    62	
    63	        if (shouldDisplaySelectedOptionOnTop) {
    64	            result.push({
    65	                title: '',
    66	                data: selectedOptions,
    67	                shouldShow: true,
    68	            });
    69	        }
    70	
    71	        if (shouldDisplayRecentlyOptions) {
    72	            if (!isEmpty) {
    73	                result.push(
    74	                    {
    75	                        title: translate('common.recents'),
    76	                        data: shouldDisplaySelectedOptionOnTop ? getUnselectedOptions(recentlyUsedCurrencyOptions) : recentlyUsedCurrencyOptions,
    77	                        shouldShow: shouldDisplayRecentlyOptions,
    78	                    },
    79	                    {title: translate('common.all'), data: shouldDisplayRecentlyOptions ? unselectedOptions : filteredCurrencies},
    80	                );
    81	            }
    82	        } else if (!isEmpty) {
    83	            result.push({
    84	                data: shouldDisplaySelectedOptionOnTop ? unselectedOptions : filteredCurrencies,
    85	            });
    86	        }
    87	
    88	        return {sections: result, headerMessage: isEmpty ? translate('common.noResultsFound') : ''};
    89	    }, [currencyList, searchValue, translate, initiallySelectedCurrencyCode, selectedCurrencies, getUnselectedOptions, recentlyUsedCurrencies]);
    90	
    91	    return (
    92	        <SelectionList
    93	            sections={sections}
    94	            ListItem={canSelectMultiple ? SelectableListItem : RadioListItem}
